function validate([room]) {
  if (room.length < 1 || room.length > 300) return 'room needs 1 to 300 rows.';
  const n = room[0].length;
  if (n < 1 || n > 300) return 'room needs 1 to 300 columns.';
  for (const row of room) {
    if (row.length !== n) return 'Every row must have the same length.';
    if (row.some(v => v !== 0 && v !== 1)) return 'Each space is 0 (empty) or 1 (object).';
  }
  if (room[0][0] !== 0) return 'The top-left space must be empty.';
  return null;
}

