function numberOfCleanRooms(room) {
  const rows = room.length;
  const cols = room[0].length;
  const dr = [0, 1, 0, -1];
  const dc = [1, 0, -1, 0];
  const seen = Array.from({ length: rows }, () => new Array(cols).fill(0));
  let r = 0;
  let c = 0;
  let dir = 0;
  let cleaned = 0;

  while ((seen[r][c] & (1 << dir)) === 0) {
    if (seen[r][c] === 0) {
      cleaned++;
    }
    seen[r][c] |= 1 << dir;
    const nr = r + dr[dir];
    const nc = c + dc[dir];
    if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && room[nr][nc] === 0) {
      r = nr;
      c = nc;
    } else {
      dir = (dir + 1) % 4;
    }
  }
  return cleaned;
}

