function numberOfCleanRooms(room) {
  const m = room.length, n = room[0].length;
  const moves = { right: [0, 1, 'down'], down: [1, 0, 'left'], left: [0, -1, 'up'], up: [-1, 0, 'right'] };
  const clean = new Set(['0,0']);
  let y = 0, x = 0, facing = 'right';
  // There are at most 4 * m * n states, so this many steps reaches every state the robot will ever be in.
  for (let step = 0; step < 4 * m * n + 4; step++) {
    const [dy, dx, turn] = moves[facing];
    const ty = y + dy, tx = x + dx;
    if (ty < 0 || ty >= m || tx < 0 || tx >= n || room[ty][tx] === 1) { facing = turn; continue; }
    y = ty; x = tx;
    clean.add(y + ',' + x);
  }
  return clean.size;
}

