function generate(rand, size) {
  const randomRoom = (m, n, density) => {
    const room = Array.from({ length: m }, () => Array.from({ length: n }, () => (rand() < density ? 1 : 0)));
    room[0][0] = 0;
    return room;
  };
  // A spiral corridor with one-cell walls, so the robot travels a long path before it loops.
  const spiralRoom = (m, n) => {
    const room = Array.from({ length: m }, () => new Array(n).fill(1));
    const dr = [0, 1, 0, -1], dc = [1, 0, -1, 0];
    const open = (y, x) => y >= 0 && y < m && x >= 0 && x < n && room[y][x] === 0;
    const inside = (y, x) => y >= 0 && y < m && x >= 0 && x < n;
    let y = 0, x = 0, d = 0, turns = 0;
    room[0][0] = 0;
    while (turns < 2) {
      const ny = y + dr[d], nx = x + dc[d];
      if (inside(ny, nx) && !open(ny, nx) && !open(ny + dr[d], nx + dc[d])) { y = ny; x = nx; room[y][x] = 0; turns = 0; }
      else { d = (d + 1) % 4; turns++; }
    }
    return room;
  };
  if (size === 'large') {
    const m = 60 + Math.floor(rand() * 41), n = 60 + Math.floor(rand() * 41);
    if (rand() < 0.5) {
      const room = spiralRoom(m, n);
      const breaks = Math.floor(rand() * 3);
      for (let k = 0; k < breaks; k++) {
        const y = Math.floor(rand() * m), x = Math.floor(rand() * n);
        if (y + x > 0) room[y][x] = 1 - room[y][x];
      }
      return [room];
    }
    return [randomRoom(m, n, rand() * 0.04)];
  }
  const m = 1 + Math.floor(rand() * 6), n = 1 + Math.floor(rand() * 6);
  if (rand() < 0.2) return [spiralRoom(m, n)];
  return [randomRoom(m, n, [0, 0.1, 0.25, 0.45][Math.floor(rand() * 4)])];
}
